SELECT card_recommendation_id AS cardRecommendationId, card_company AS cardCompany, card_name AS cardName, benefit_summary AS benefitSummary, card_url AS cardUrl, card_image AS cardImage, benefit_category AS benefitCategory FROM CardRecommendation WHERE 1 = 1
AND benefit_category IN
#{category}
AND card_type = #{cardType}
